const target = msg.metadata.target;

if (!target || !target.api_key || !target.client_specific.log_id) {
    node.error("Rayvn not configured on this connection");
    return null;
}

msg.url = global.get("parat_bridge").base_urls.rayvn
    + "/logs/" + target.client_specific.log_id + "/entry";

msg.headers = {
    "Authorization": "Bearer " + target.api_key,
    "Content-Type":  "application/json",
    "Accept":        "application/json"
};

return msg;

node.warn("[RAYVN POST] status: " + msg.statusCode + ", url: " + msg.url + ", response: " + JSON.stringify(msg.payload).substring(0, 300));
msg.topic = "response"

if (msg.statusCode == 200) {
    msg.result = true
} else {
    msg.result = false
}

return msg;

node.warn("[DEBUG] File path triggered, file: " + msg.payload.files[0].name);

var target = msg.metadata.target;

msg.entryPayload = msg.payload;

var file = msg.payload.files[0];
var boundary = "----ParatBridge" + Date.now();

var header = "--" + boundary + "\r\n" +
    "Content-Disposition: form-data; name=\"file\"; filename=\"" + file.name + "\"\r\n" +
    "Content-Type: " + file.type + "\r\n\r\n";
var footer = "\r\n--" + boundary + "--\r\n";

var headerBuf = Buffer.from(header, "utf8");
var footerBuf = Buffer.from(footer, "utf8");
msg.payload = Buffer.concat([headerBuf, file.buffer, footerBuf]);

msg.url = global.get("parat_bridge").base_urls.rayvn + "/files";
msg.headers = {
    "Authorization": "Bearer " + target.api_key,
    "Content-Type": "multipart/form-data; boundary=" + boundary
};

return msg;

node.warn("[FILE UPLOAD] status: " + msg.statusCode + ", response: " + JSON.stringify(msg.payload).substring(0, 500));
var fileId = msg.payload.id;
node.warn("[FILE UPLOAD] fileId: " + fileId);

msg.payload = msg.entryPayload;
msg.payload.files = [fileId];

delete msg.entryPayload;

return msg;

const file = msg.payload.files[0];
if (!file || !file.buffer) return msg;

const isVideo = file.type && file.type.startsWith('video/');
const isAudio = file.type && file.type.startsWith('audio/');
if (!isVideo && !isAudio) return msg;

const ONE_MB = 1 * 1024 * 1024;
if (file.buffer.length <= ONE_MB) return msg;

const tmpDir = os.tmpdir();
const ts = Date.now();
const inputPath = path.join(tmpDir, 'parat_in_' + ts + path.extname(file.name));
const outputExt = isVideo ? '.mp4' : '.aac';
const outputPath = path.join(tmpDir, 'parat_out_' + ts + outputExt);

fs.writeFileSync(inputPath, file.buffer);

// Get duration with ffprobe
return new Promise((resolve) => {
    childProcess.execFile('ffprobe', [
        '-v', 'error',
        '-show_entries', 'format=duration',
        '-of', 'default=noprint_wrappers=1:nokey=1',
        inputPath
    ], { timeout: 15000 }, (err, stdout) => {
        const duration = parseFloat(stdout);
        if (err || isNaN(duration) || duration <= 0) {
            node.warn('[FFMPEG] Could not determine duration: ' + (err ? err.message : stdout));
            try { fs.unlinkSync(inputPath); } catch (e) { }
            return resolve(msg);
        }

        // Target: 1MB minus 32KB safety margin
        const targetBytes = ONE_MB - (32 * 1024);
        const audioBitrate = 64000;
        const totalBitrate = Math.floor((targetBytes * 8) / duration);
        const videoBitrate = Math.max(totalBitrate - audioBitrate, 50000);

        const args = ['-i', inputPath, '-y'];

        if (isVideo) {
            args.push(
                '-vcodec', 'libx264',
                '-b:v', videoBitrate + '',
                '-maxrate', videoBitrate + '',
                '-bufsize', Math.floor(videoBitrate / 2) + '',
                '-preset', 'fast',
                '-vf', 'scale=min(640\\,iw):min(480\\,ih):force_original_aspect_ratio=decrease,scale=trunc(iw/2)*2:trunc(ih/2)*2',
                '-acodec', 'aac',
                '-b:a', '64k',
                '-movflags', '+faststart'
            );
        } else {
            const audioBr = Math.min(Math.floor(totalBitrate), 128000);
            args.push('-acodec', 'aac', '-b:a', audioBr + '');
        }

        args.push(outputPath);

        childProcess.execFile('ffmpeg', args, { timeout: 120000 }, (error) => {
            try {
                if (error) {
                    node.warn('[FFMPEG] Compression failed: ' + error.message);
                    fs.unlinkSync(inputPath);
                    try { fs.unlinkSync(outputPath); } catch (e) { }
                    return resolve(msg);
                }

                const compressed = fs.readFileSync(outputPath);
                node.warn('[FFMPEG] ' + file.name + ': ' + file.buffer.length + ' → ' + compressed.length + ' bytes (target: ' + targetBytes + ', duration: ' + duration.toFixed(1) + 's)');

                file.buffer = compressed;
                if (isVideo) {
                    file.name = file.name.replace(/\.[^.]+$/, '') + '.mp4';
                    file.type = 'video/mp4';
                }

                fs.unlinkSync(inputPath);
                fs.unlinkSync(outputPath);
                resolve(msg);
            } catch (e) {
                node.warn('[FFMPEG] Cleanup error: ' + e.message);
                try { fs.unlinkSync(inputPath); } catch (e) { }
                try { fs.unlinkSync(outputPath); } catch (e) { }
                resolve(msg);
            }
        });
    });
});

const file = msg.payload.files && msg.payload.files[0];
if (!file || !file.url) return msg;

const baseUrl = global.get("parat_bridge").base_urls.wasos;
const source = msg.metadata.source;
const fileUrl = baseUrl + file.url;

const headers = {};
if (source && source.client_specific && source.client_specific.api) {
    headers["x-api-key"] = source.client_specific.api.key;
}

return new Promise((resolve, reject) => {
    const client = fileUrl.startsWith("https") ? https : http;

    client.get(fileUrl, { headers }, (res) => {
        if (res.statusCode !== 200) {
            node.warn("[DOWNLOAD] Failed: status " + res.statusCode);
            return resolve(msg);
        }

        const chunks = [];
        res.on("data", chunk => chunks.push(chunk));
        res.on("end", () => {
            file.buffer = Buffer.concat(chunks);
            node.warn("[DOWNLOAD] " + file.name + ": " + file.buffer.length + " bytes");
            resolve(msg);
        });
        res.on("error", (err) => {
            node.warn("[DOWNLOAD] Error: " + err.message);
            resolve(msg);
        });
    }).on("error", (err) => {
        node.warn("[DOWNLOAD] Request error: " + err.message);
        resolve(msg);
    });
});
